  @Test
  public void testSpecialItemLevelSerializationOutofrange() throws IOException {
    for (long value : new long[] {9007199254740992L, -9007199254740992L}) {
      final SpecialItem instance =
        Jsonization.Deserialize.deserializeSpecialItem(
          loadTheFirstExpected("SpecialItem"));

      instance.setLevel(value);

      try {
        Jsonization.Serialize.toJsonObject(instance);
        fail(
          "Expected the serialization to fail at "
            + "getLevel()"
            + ", but it succeeded");
      } catch (Jsonization.SerializeException exception) {
        assertEquals(
          "getLevel()",
          exception.getPath().orElse(null));
      }
    }
  } // public void testSpecialItemLevelSerializationOutofrange
